public:
    vector<int> q;

    FrontMiddleBackQueue() {}

    void pushFront(int val) { q.insert(q.begin(), val); }

    void pushMiddle(int val) { q.insert(q.begin() + q.size() / 2, val); }

    void pushBack(int val) { q.push_back(val); }

    int popFront() {
        if (q.empty()) return -1;
        int v = q.front();
        q.erase(q.begin());
        return v;
    }

    int popMiddle() {
        if (q.empty()) return -1;
        int idx = (q.size() - 1) / 2;
        int v = q[idx];
        q.erase(q.begin() + idx);
        return v;
    }

    int popBack() {
        if (q.empty()) return -1;
        int v = q.back();
        q.pop_back();
        return v;
    }
};

